(() => {
  'use strict';
  const translations = {"\uc774\uc820 \ud3d0\ud5c8\uac00 \ub418\uc5b4\ubc84\ub9b0 \uc81c\uc0ac\uc7a5\uc758 \ub9c8\uc744\uc5d0 \ub2e4\ub2e4\ub978 \uc544\ub3c8\uc740 \ub9c8\uc744 \ub4a4\ud3b8\uc5d0 \uc788\ub358 \uc81c\uc0ac\uc758 \ub3d9\uad74\uc5d0\uc11c \ud55c \ub178\uc778\uc758 \ud658\uc601\uacfc \ub9cc\ub098\uac8c \ub41c\ub2e4. \uadf8\ub294 \uc544\ub3c8\uc5d0\uac8c \uad50\ud669\uc758 \uacfc\uac70\uc5d0 \ub300\ud574\uc11c \uc774\uc57c\uae30\ub97c \ud574 \uc900\ub2e4. \uad50\ud669\uc740 \uc6d0\ub798 \uc81c\uc0ac\uc7a5 \ub9c8\uc744\uc758 \uc0ac\ub78c\uc774\uc5c8\ub2e4. \uadf8\ub294 \uc5b4\ub9b4 \ub54c\ubd80\ud130 \ub9c8\ubc95\uc5d0 \ub9e4\uc6b0 \ub2a5\ud588\uace0 \uc0c8\ub85c\uc6b4 \ub9c8\ubc95\uc744 \uc775\ud788\ub824\ub294 \uc695\uad6c\uac00 \ub9e4\uc6b0 \uac15\ud55c \uc790\uc600\ub2e4. \uc81c\uc0ac\uc7a5\uc758 \ub9c8\uc744\uc5d0\ub294 \uc77c\ubc18 \ub9c8\uc744 \uc0ac\ub78c\ub4e4\uc5d0\uac8c\ub294 \uacf5\uac1c\ub418\uc9c0 \uc54a\ub294 \uae08\uc11c\ub4e4\uc774 \uba87 \uad8c \uc788\uc5c8\ub294\ub370 \uc5b4\ub9b0 \uad50\ud669\uc740 \uadf8 \uae08\uc11c\uc5d0 \uae30\ub85d\ub418\uc5b4 \uc788\ub294 \uae08\uae30 \ub9c8\ubc95\ub4e4\uc5d0 \ud638\uae30\uc2ec\uc744 \uac00\uc838 \uadf8 \uae08\uc11c\ub4e4\uc744 \ubab0\ub798 \ubcf4\ub2e4\uac00 \ucad3\uaca8\ub09c\ub2e4. \ucd94\ubc29\ub2f9\ud55c \uad50\ud669\uc740 \uc2e0\ubd84\uc744 \uc228\uae30\uace0 \uad50\ud669\uc774 \ub41c \ud6c4 \uadf8\uc758 \uad8c\ub825\uc73c\ub85c \uc81c\uc0ac\uc7a5\uc758 \ub9c8\uc744\uc744 \uacf5\uaca9\ud558\uc5ec \uadf8 \uae08\uc11c\ub4e4\uc744 \uc190\uc5d0 \ub123\ub294\ub2e4. \uae08\uae30\uc758 \ub9c8\ubc95\ub4e4\uc744 \uc775\ud78c \uad50\ud669\uc740 \ub9c8\ubc95\uc758 \uc601\ud5a5\uc73c\ub85c \uc810\uc810 \uc090\ub6a4\uc5b4\uc838\ub9cc \uac00\uace0 \uacb0\uad6d\uc740 \ud3ed\uc815\uc744 \ud589\ud558\ub294 \uc545\uad70\uc774 \ub418\uc5b4 \ubc84\ub9b0 \uac83\uc774\uc5c8\ub2e4. \ub178\uc778\uc758 \ud658\uc601\uc740 \ubc14\ub85c \ud3c9\ubbfc \ub808\uc9c0\uc2a4\ud0d5\uc2a4\uc758 \uc6b0\ub450\uba38\ub9ac\uc5d0\uac8c '\ub4dc\ub798\uace4' \uc18c\ud658\uc220\uc744 \uac00\ub974\uccd0 \uc900 \ub178\uc778\uc774\uc5c8\uc73c\uba70 \uadf8\ub294 \ub9ce\uc740 '\ub4dc\ub798\uace4'\ub4e4\uc774 \uc0ac\ub77c\uc9c4 \uc9c0\uae08 \uad50\ud669\uc758 \uc554\ud751 \ub9c8\ubc95\uc5d0 \ub300\ud56d\ud558\uae30 \uc704\ud574\uc120 '\ud654\uc774\ud2b8 \ub4dc\ub798\uace4'\uc758 \ud798\uc744 \ube4c\ub9ac\ub294 \uc218\ubc16\uc5d0\ub294 \uc5c6\ub2e4\ub294 \uc815\ubcf4\ub97c \uc8fc\uace0 '\ub4dc\ub798\uace4'\uc744 \uc18c\ud658\ud560 \uc218 \uc788\ub294 \ubc29\ubc95\uc744 \uac00\ub974\uccd0 \uc900\ub2e4. \uc774\uc5d0 \uc544\ub3c8\uc740 '\ub4dc\ub798\uace4'\uc744 \ub9cc\ub098\uae30 \uc704\ud574 \uafc8\uc758 \uc2e0\uc778 '\ud560\ub86c'\uc758 \uc81c\ub2e8\uc774 \uc788\ub294 SHEREG\uc758 ILLEM\uc73c\ub85c \ud5a5\ud55c\ub2e4.": "At the ruined priests\u2019 village, Adon meets an old man\u2019s apparition in a cave behind the settlement. The apparition tells him that the pope once lived there and was gifted in magic. As a child he secretly read forbidden books and was exiled. After becoming pope under a concealed identity, he attacked the village and seized the books. The forbidden magic gradually corrupted him into a tyrant. The old man, who taught Shem to summon dragons, explains that only the White Dragon can oppose the pope\u2019s dark magic now that so many dragons have vanished. He teaches Adon how to summon it, and Adon travels to Illem in Shereg, where Hallom\u2019s altar stands.", "ILLEM\uc5d0 \ub3c4\ucc29\ud55c \uc544\ub3c8\uc740 ILLEM \uc678\uacfd\uc758 \ud55c \ub358\uc83c\uc5d0\uc11c \uc2e0\uc758 \uc804\uc7c1\uc744 \uc885\uc2dd\uc2dc\ud0a8 \uc7a5\ubcf8\uc778\uc778 '\ud654\uc774\ud2b8 \ub4dc\ub798\uace4'\uc744 \ub9cc\ub098\uac8c \ub418\uace0 '\ud654\uc774\ud2b8 \ub4dc\ub798\uace4'\uc740 \uc544\ub3c8\uc5d0\uac8c '\ud560\ub86c'\uc758 \uc2dc\ud5d8\uc744 \ud1b5\uacfc\ud560 \uac83\uc744 \uc694\uad6c\ud55c\ub2e4. '\ud560\ub86c'\uc758 \uc2dc\ud5d8\uc744 \ud1b5\uacfc\ud55c \uc544\ub3c8\uc740 \ub2f9\ub2f9\ud788 '\ub4dc\ub798\uace4'\uc758 \uc8fc\uc778\uc73c\ub85c\uc368 \uc778\uc815\uc744 \ubc1b\ub294\ub2e4. \uc544\ub3c8\uc740 '\ud654\uc774\ud2b8 \ub4dc\ub798\uace4'\uacfc \ud568\uaed8 \uad50\ud669\uccad\uc774 \uc788\ub294 AESH\ub85c \ud5a5\ud55c\ub2e4. \uad50\ud669\uccad\uc5d0\uc11c \ubb34\uc218\ud55c '\uac08\uac00\ub3cc'\ub4e4\uacfc \uc554\ud751\ub9c8\ubc95\uc73c\ub85c \uc18c\ud658\ub41c \uc218\ub9ce\uc740 '\ubaac\uc2a4\ud130'\ub4e4\uacfc\uc758 \uc804\ud22c\ub97c \uac70\uccd0 \uad50\ud669\uacfc \ub300\uc801\ud558\uac8c \ub41c \uc544\ub3c8\uc740 \ud798\uacb9\uac8c \uad50\ud669\uc744 \ubb3c\ub9ac\uce5c\ub2e4.": "In a dungeon outside Illem, Adon meets the White Dragon, who ended the war of the gods. The dragon asks him to pass Hallom\u2019s trial. Having succeeded, Adon is recognised as the dragon\u2019s master. Together they travel to the papal court in Aesh. After fighting countless Gargadol and monsters summoned by dark magic, Adon confronts the pope and defeats him after a hard struggle.", "dispel patch \ub2e4\uc6b4\ub85c\ub4dc": "Dispel patch download", "\uc774\ubc88 \ud328\uce58": "This patch", "\uc5d0\uc11c \uace0\uccd0\uc84c\uac70\ub098 \ucd94\uac00\ub41c \ubd80\ubd84": "changes and additions", "< \uc774\ubc88 \ubc84\uc83c \ud328\uce58\uc5d0\uc11c \uc218\uc815\ub41c \uc0ac\ud56d\ub4e4\uc785\ub2c8\ub2e4. >": "< Fixes in this patch >", "1. \ub85c\ub529\uc2dc \uac00\uc9c0\uace0 \uc788\ub358 \uc544\uc774\ud15c\ub4e4\uc774 \uc774\uc0c1\ud558\uac8c \ub418\ub294 \ud604\uc0c1": "1. Items behaving incorrectly after loading.", "2. \ud30c\ud2f0\uc5d0\uac8c \ub9c8\ubc95\uc0ac\uc6a9\uc2dc \ub9c8\uc6b0\uc2a4\ub85c \uc120\ud0dd\uc774 \ubd88\ud3b8\ud55c\uc810": "2. Difficulty selecting party members with the mouse when casting spells.", "3. \ud2b9\uc815 \ub85c\ube0c\ub97c \uc785\uc5c8\ub2e4 \ubc97\uc5c8\uc744 \ub54c \uba38\ub9ac\uce74\ub77d\uc774 \uc5c6\uc5b4\uc9c0\ub294 \ud604\uc0c1": "3. Hair disappearing after removing certain robes.", "4. \ud30c\ud2f0\ub97c \ub300\uc6d0\uc73c\ub85c \uac00\uc9c0\uace0 \uc788\uc744 \ub54c \ub85c\ub529\uc2dc \uc708\ub3c4\uc6b0\ub85c \ube60\uc838\ub098\uac00\ub294 \ud604\uc0c1": "4. A crash to Windows when loading with party members.", "5. \ubca8\ud2b8\uc5d0 \uc788\ub358 \uc57d\ucd08\ub97c \ud074\ub9ad\ud574\uc11c \uce90\ub9ad\ud130\ub97c \ucc0d\uc73c\uba74 \uc704\uc637\uc774 \ubc97\uaca8\uc9c0\ub294 \ud604\uc0c1": "5. A character\u2019s upper clothing coming off when an herb from the belt was used on them.", "6. \uc57d\ucd08\ub97c \ub4e4\uace0 \ub85c\ub4dc,\uc138\uc774\ube0c\uc2dc\uc758 \ubb38\uc81c\uc810": "6. Problems saving or loading while holding an herb.", "7. \ubc29\ud328\ub97c \uc7a5\ucc29\uc2dc \ub2e4\uc6b4\ub418\ub294 \ud604\uc0c1": "7. A crash when equipping a shield.", "8. \uc0c1\uc810\uc5d0\uc11c \uc544\uc774\ud15c\uc774 \ubb34\ud55c\ub300\ub85c \ud314\uc544\uc9c0\ub294 \ud604\uc0c1": "8. Items could be sold an unlimited number of times in shops.", "9. \uc7a5\ucc29\ud560 \uc218 \uc5c6\ub294 \ubc29\uc5b4\uad6c\ub098 \ubb34\uae30\ub97c \ud45c\uc2dc\ud310\ub4f1\uc5d0 \ud074\ub9ad\ud558\uba74 \uc7a5\ucc29\ud560 \uc218 \uc788\ub294 \uc0c1\ud0dc\ub85c \ubcc0\ud558 \ub294 \ud604\uc0c1": "9. Unusable weapons or armour could become equippable when clicked on certain interface panels.", "10. \uc8fc\uc778\uacf5\uc774 \ud154\ub808\ud3ec\ud2b8\ub97c \ud558\uac70\ub098 \ub8ec\uc2a4\ud1a4\uc744 \uc0ac\uc6a9\ud588\uc744 \uacbd\uc6b0 \ud30c\ud2f0\ub294 \uc774\ub3d9\uc774 \ub418\uc9c0\uc54a\ub294 \ubb38 \uc81c": "10. Party members did not follow when the protagonist teleported or used a runestone.", "11. \uce74\uc0b0\uc744 \ub9cc\ub098\uace0 \ub09c \ud6c4 \ub2e4\uc774\uc5b4\ub9ac\ub97c \uc5f4\uba74 \ud295\uae30\ub294 \ubc84\uadf8\uac00 \uc218\uc815\ub418\uc5c8\uc2b5\ub2c8\ub2e4.": "11. Fixed a crash when opening the diary after meeting Kasan.", "12. \ud53c\uc774\ub07c \ub808\uc9c0\uc2a4\ud134\uc2a4\uac00 6\uc5d0\uc11c 7\ub85c \uc218\uc815\ub418\uc5c8\uc2b5\ub2c8\ub2e4.": "12. Changed blood moss resistance from 6 to 7.", "13. \ub9e8\ub4dc\ub798\uc774\ud06c\uc758 \ubfcc\ub9ac \uc544\uc774\ud15c \uc815\ubcf4\uc5d0\uc11c Resis 5\uac00 Resist 12\ub85c \uc218\uc815\ub418\uc5c8\uc2b5\ub2c8\ub2e4.": "13. Corrected mandrake root information from Resist 5 to Resist 12.", "14. \ub4dc\ub808\uc774\ud06c \uc18c\ud0d5 \uc774\ubca4\ud2b8 \uc885\ub8cc \ucc98\ub9ac\uac00 \uc54a\ub418\ub358 \uac83\uc774 \uc218\uc815\ub418\uc5c8\uc2b5\ub2c8\ub2e4.": "14. Fixed completion of the drake extermination event.", "15. \uc545\ub9c8\uc758 \ud050\ube0c \uc774\ubca4\ud2b8 \uc885\ub8cc \ucc98\ub9ac\uac00 \uc54a\ub418\ub358 \uac83\uc774 \uc218\uc815\ub418\uc5c8\uc2b5\ub2c8\ub2e4.": "15. Fixed completion of the Devil\u2019s Cube event.", "16. \ubc30\ud2c0\ub85c\ube0c \uc544\uc774\ud15c \uc815\ubcf4\uc5d0\uc11c REQ STR\uc774 REQ WIS\ub85c \uc218\uc815\ub418\uc5c8\uc2b5\ub2c8\ub2e4.": "16. Corrected the battle robe requirement from STR to WIS.", "17. \ub291\ub300 \ub358\uc83c\uc5d0\uc11c \uc6d4\uc11d \uc81c\ub2e8\uc774 \uc624\ub3d9\uc791 \ub418\ub358 \uac83\uc774 \uc218\uc815\ub418\uc5c8\uc2b5\ub2c8\ub2e4.": "17. Fixed the moonstone altar in the wolf dungeon.", "18. \uc250\ub808\uadf8\uc640 \uc58c\uc758 \ubd80\ud65c\uc758 \uc81c\ub2e8\uc774 \uc624\ub3d9\uc791 \ub418\ub358 \uac83\uc774 \uc218\uc815\ub418\uc5c8\uc2b5\ub2c8\ub2e4.": "18. Fixed the resurrection altars in Shereg and Yaem.", "19. \ube5b\uc758 \ubcf4\uc11d\uc774 \ud558\ub098 \ub098\uc624\uc9c0 \uc54a\ub358 \uac83\uc774 \uc218\uc815\ub418\uc5c8\uc2b5\ub2c8\ub2e4. \ub9c8\uc9c0\ub9c9 \ube5b\uc758 \ubcf4\uc11d\uc740 \ubc1c\ub85d\uc758": "19. Fixed a missing Jewel of Light. The last jewel is on the first floor of Balrog\u2019s dungeon.", "\ub358\uc83c 1\uce35\uc5d0 \uc788\uc73c\uba70 \ud604\uc7ac\uae4c\uc9c0 \ubc1c\ub85d\uc758 \ub358\uc83c\uc5d0 \ud55c\ubc88\ub3c4 \uc54a\ub4e4\uc5b4\uac00\uc2e0 \uc720\uc800\ub2d8\ub4e4\uaed8\uc11c\ub294 \ud328\uce58\ub97c": "If you have never entered Balrog\u2019s dungeon, installing the patch", "\uae54\uace0 \ub098\uba74 \ube5b\uc758 \ubcf4\uc11d\uc774 \ub098\uc62c \uac83\uc785\ub2c8\ub2e4. \uc774\ubbf8 \ubc1c\ub85d\uc758 \ub358\uc83c\uc5d0 \ub4e4\uc5b4\uac00\uc168\ub358 \ubd84\ub4e4\uc740 \uc138\uc774\ube0c": "should make the jewel appear. If you have already entered it,", "\ud30c\uc77c\uc758 \ud638\ud658\uc131 \ubb38\uc81c\ub85c \ud328\uce58\ub97c \uae54\uc544\ub3c4 \ube5b\uc758 \ubcf4\uc11d\uc774 \ub098\uc624\uc9c0 \uc54a\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4.. \uc774\uc810": "save-file compatibility may prevent the jewel from appearing even after patching.", "\uc815\ub9d0 \uc8c4\uc1a1\ud569\ub2c8\ub2e4. 20. \uc720\ub2c8\ucf58, \ubc14\uc774\ucf58 \uc774\ub984\uc774 \ubc14\ub010 \uac83\uc774 \uc218\uc815\ub418\uc5c8\uc2b5\ub2c8\ub2e4.": "We apologise. 20. Corrected the swapped unicorn and bicorn names.", "21. \ubc14\ub78c\uc758 \uc815\ub839 \uc774\ubca4\ud2b8 \uc2dc\uc5d0 \uc2e4\ud504\uc758 \ucda4 \uc8fc\ubb38\uc11c\uac00 \uc90d\uae30 \ud798\ub4e0 \uc790\ub9ac\uc5d0 \ub5a8\uc5b4\uc9c0\ub358 \uac83\uc744 \uc218 \uc815\ud558\uc600\uc2b5\ub2c8\ub2e4.": "21. Fixed the Sylph\u2019s Dance scroll dropping in a hard-to-reach location during the wind spirit event.", "22. \ubd88\uc758 \uc655 \ud478\ub974 \uc774\ubca4\ud2b8 \uc2dc\uc5d0 \uc774\ub984\uc774 \uc798\ubabb \ub098\uc624\ub358 \uac83\uc774 \uc218\uc815\ub418\uc5c8\uc2b5\ub2c8\ub2e4.": "22. Corrected a name during the Fire King Pur event.", "23. \ub291\ub300 \ub358\uc83c \uc774\ubca4\ud2b8 \uc885\ub8cc \ucc98\ub9ac\uac00 \uc54a\ub418\ub358 \uac83\uc774 \uc218\uc815\ub418\uc5c8\uc2b5\ub2c8\ub2e4.": "23. Fixed completion of the wolf dungeon event.", "24. \ubaa8\ub4e0 \ud544\ub4dc \ub9f5\uc5d0\uc11c\uc758 \uc5f4\uc5b4\ubcfc \uc218 \uc5c6\ub358 \uacf3\uc5d0 \uc788\ub358 \uc0c1\uc790\ub4e4\uc774 \uc218\uc815\ub418\uc5c8\uc2b5\ub2c8\ub2e4.": "24. Fixed inaccessible chests on field maps.", "25. Fetae\uc758 \ud06c\ub80c\ub514\ub77c\ub294 \uae30\uc220 \uac00\ub974\uccd0 \uc8fc\ub294 \uc5ec\uc790 NPC\uc758 \ubaa9\uc18c\ub9ac\uc640 \uc774\ubca4\ud2b8\uac00 \uc815\uc0c1\uc801\uc73c\ub85c \uc218\uc815\ub418\uc5c8\uc2b5\ub2c8\ub2e4.": "25. Fixed the voice and event for the woman in Fetae who teaches the Crendy skill.", "26. \uc58c\uc758 \uc2a4\ud478\ud0a4 \ucf58 \uc774\ubca4\ud2b8\uac00 \uc5ec\ub7ec\uac00\uc9c0 \uc0ac\uc815\uc0c1 \uc0ad\uc81c\ub420 \uc218 \ubc16\uc5d0 \uc5c6\uc5c8\uc2b5\ub2c8\ub2e4.": "26. Yaem\u2019s Spooky Corn event had to be removed due to various circumstances.", "\uc774 \uc810 \uc720\uc800\ubd84\ub4e4\uaed8 \uba38\ub9ac\uc219\uc5ec \uc0ac\uacfc\ub4dc\ub9bd\ub2c8\ub2e4. \uc815\ub9d0 \uc8c4\uc1a1\ud569\ub2c8\ub2e4.": "We sincerely apologise to players for this.", "27. \uc5d0\uc26c\uc758 \uc2a4\ud1a4 \uace0\ub818\uacfc \ub9ac\uce58 \ub4f1 \uc77c\ubd80 \ubaac\uc2a4\ud130\ub4e4\uc774 \uc0c8\ub85c \uc0dd\uc131\ub418\uc9c0 \uc54a\uc558\ub358 \uac83\uc774 \uc218\uc815\ub418 \uc5c8\uc2b5\ub2c8\ub2e4.": "27. Fixed some monsters, including stone golems and liches in Aesh, not respawning.", "28. \uc250\ub808\uadf8\uc758 \ubc31\uacf0\uc758 \ubc1c\ubc14\ub2e5 \uc774\ubca4\ud2b8\uc5d0\uc11c \ubc31\uacf0\uc774 \ubc1c\ubc14\ub2e5\uc744 \uc54a\ub5a8\uc5b4\ub728\ub9ac\ub358 \uac83\uc774 \uc218\uc815\ub418\uc5c8 \uc2b5\ub2c8\ub2e4.": "28. Fixed the white bear failing to drop its paw in Shereg\u2019s white bear paw event.", "29. \uc5b8\ub370\ub4dc\uc758 \ud314 \uc544\uc774\ud15c\uc744 \ub5a8\uc5b4\ub728\ub9ac\ub358 \ubaac\uc2a4\ud130\uac00 \ub354\uc774\uc0c1 \uc0c8\ub85c \uc0dd\uc131\ub418\uc9c0 \uc54a\uac8c \uc218\uc815\ub418\uc5c8 \uc2b5\ub2c8\ub2e4.": "29. Prevented the monster that dropped an undead arm from respawning.", "* 27, 28, 29\ubc88 \uc218\uc815\uc0ac\ud56d\uc740 \uae30\uc874 \uc138\uc774\ube0c\ud654\uc77c\ub85c \ud50c\ub808\uc774\ud558\uc2e4\ub54c\uc5d0\ub294 \uc801\uc6a9\uc774 \uc54a\ub420\uc218\ub3c4 \uc788 \uc2b5\ub2c8\ub2e4.": "* Fixes 27\u201329 may not apply when using existing save files.", "< \uc774\ubc88 \ubc84\uc83c \ud328\uce58\uc5d0\uc11c \ucd94\uac00\ub41c \uc0ac\ud56d\ub4e4\uc785\ub2c8\ub2e4. >": "< Additions in this patch >", "1. \ubc30\uacbd\uc74c\uacfc \ud6a8\uacfc\uc74c\uc758 \uc74c\ub7c9\uc870\uc808\uc774 \uac00\ub2a5\ud574 \uc84c\uc2b5\ub2c8\ub2e4.": "1. Background music and sound-effect volumes can now be adjusted.", "\ubc30\uacbd\uc74c\uc758 \uc74c\ub7c9\uc870\uc815\uc740 [ \ud0a4\uc640 ] \ud0a4 \uc785\ub2c8\ub2e4.": "Use the [ and ] keys for background music.", "\ud6a8\uacfc\uc74c\uc758 \uc74c\ub7c9\uc870\uc815\uc740 < \ud0a4\uc640 > \ud0a4 \uc785\ub2c8\ub2e4.": "Use the < and > keys for sound effects.", "\uac8c\uc784\uc5d0\uc11c \uc870\uc815\ub41c \ubc30\uacbd\uc74c, \ud6a8\uacfc\uc74c\uc758 \ubcfc\ub968\uc740 \uc800\uc7a5\ub429\ub2c8\ub2e4.": "The game saves the adjusted volume levels.", "\uc555\ucd95\uc744 \uc784\uc2dc\ub85c \ub9cc\ub4e0 \ud3f4\ub354\uc5d0 \ud480\uace0 Patch131.exe\ud654\uc77c\uc744 \uc2e4\ud589\uc2dc\ud0a4\uba74 \ud328\uce58\uac00 \ub429\ub2c8\ub2e4.": "Extract the archive to a temporary folder and run Patch131.exe to install the patch.", "\ud328\uce58\uac00 \ub05d\ub098\uace0 \ub09c\ud6c4\uc5d0\ub294 \uc784\uc2dc\ub85c \ub9cc\ub4e0 \ud3f4\ub354\uc640 \uadf8\uc548\uc758 \ud654\uc77c\ub4e4\uc740 \uc9c0\uc6b0\uc2ed\uc2dc\uc624.": "After patching, delete the temporary folder and its contents.", "FETAE\ub85c \uac04 \uc544\ub3c8\uc740 \uac70\uae30\uc11c \ud55c \uc9c0\ubc29 \uc720\uc9c0\ub97c \ub9cc\ub098\uace0 \uadf8\uc5d0\uac8c\uc11c \ub808\uc9c0\uc2a4\ud0d5\uc2a4\uc5d0\uac8c \uac74\ub124\uc904 \uc790\uae08\uacfc \ub808\uc9c0\uc2a4\ud0d5\uc2a4\uc758 \uc6b0\ub450\uba38\ub9ac\uc5d0\uac8c \uc804\ud574 \uc904 \ud3b8\uc9c0\ub97c \ubc1b\ub294\ub2e4. \uadf8 \ubb34\ub835 SHEREG\uad6d\uc758 \uad6d\uc655\uc740 \uad50\ud669\uc758 \uc624\ub79c \uc804\uc7c1\uc5d0 \ubc18\uae30\ub97c \ub4e4\uace0 \uc774\ub2e8 \ud0c4\uc555 \uc911\uc9c0\ub97c \uc694\uccad\ud55c\ub2e4. \uc774\uc5d0 \uad50\ud669\uccad\uc740 SHEREG\uad6d\uc774 \uc2e0\uc758 \ub9d0\uc744 \uc5b4\uae34\ub2e4\uba70 \ud654\ub97c \ub0b4\uc5c8\uace0 \ub2e4\ub978 \uc655\uad6d\ub4e4\uc744 \uc120\ub3d9\ud558\uc5ec SHEREG\uad6d\uc744 \uacf5\uaca9\ud558\uac8c \ub41c\ub2e4. \ub2e4\ub978 \ub098\ub77c\ub4e4\uc740 \uc790\uad6d\ub4e4\uc758 \uc704\uc0c1 \ud655\ubcf4\uc640 \uc601\ud1a0 \ud655\ubcf4\ub97c \uc704\ud574 SHEREG\ub97c \uce68\uacf5\ud558\uace0 \ub300\ub959\uc740 \uc655\uad6d\uac04\uc758 \uc804\uc7c1\uc5d0 \ud729\uc2f8\uc774\uac8c \ub41c\ub2e4. \uc5b4\uc9c0\ub7ec\uc6b4 \ub300\ub959\uc758 \uc815\uc138\ub97c \ud0c0\uace0 \uace7 \uc5d8\ub85c\ud798\uc73c\ub85c\uc758 \uae38\uc774 \uc5f4\ub9b4 \uac83\uc774\ub77c\ub294 \uc18c\ubb38\uc774 \ud3c9\ubbfc\ub4e4 \uc0ac\uc774\uc5d0 \ub04a\uc784\uc5c6\uc774 \ub3cc\uace0 \uadf8 \uc18c\ubb38\uc73c\ub85c \ub300\ub959\uc740 \ub354\uc6b1 \ud63c\ub780\uc5d0 \ube60\uc9c4\ub2e4.\uc790\uae08\uacfc \ud3b8\uc9c0\ub97c \uc804\ud574\uc904 \ubaa9\uc801\uc73c\ub85c \ub2e4\uc2dc TERAS\ub97c \ucc3e\uc740 \uc544\ub3c8\uc740 \ud55c\ub3d9\uc548 \ub808\uc9c0\uc2a4\ud0d5\uc2a4\uc758 \ubcf8\ubd80\uc5d0\uc11c \uc9c0\ub0b4\uac8c \ub418\uace0 \uc6b0\uc5f0\ud788 \uc260\uacfc \uadf8\uc758 \uce21\uadfc\ub4e4\uc774 \ubc8c\ub9ac\ub294 \ub9d0\ub2e4\ud23c\uc744 \ub4e3\uac8c \ub41c\ub2e4. \uadf8\ub4e4\uc740 \uc5d8\ub85c\ud798\uc758 \uac15\ub9bc\uc744 \ube44\ub294 \ud589\uc0ac\uc5d0 \ub300\ud574 \uc758\uacac \ub300\ub9bd\uc744 \ubcf4\uc774\uace0 \uc788\uc5c8\ub2e4. FETAE\uc758 \uc720\uc9c0\ub294 \uc260\uc5d0\uac8c \uc5d8\ub85c\ud798\uc73c\ub85c\uc758 \uae38\uc744 \uc5ec\ub294 \ubc29\ubc95\uc744 \ubc1c\uacac\ud588\ub2e4\ub294 \ud3b8\uc9c0\ub97c \ubcf4\ub0b4\uc654\uace0 \uadf8\ub7ec\uae30 \uc704\ud574\uc120 \uc0ac\ub78c\ub4e4\uc758 \uac15\ub9bc\uc81c\uac00 \ud544\uc694\ud558\ub2e4\uace0 \uc804\ud574 \uc628 \uac83\uc774\ub2e4. \uc774\uc5d0 \uc260\uc740 \uc5d8\ub85c\ud798\uc740 \uc18c\ubb38\uc77c \ubfd0\uc774\uba70 \ub9ce\uc740 \uc0ac\ub78c\ub4e4\uc774 \uadf8\ub807\uac8c \uacf5\uac1c\uc801\uc73c\ub85c \ubaa8\uc774\ub294 \uac83\uc740 \uc704\ud5d8\ud558\ub2e4\uba70 \ubc18\ub300\ub97c \ud588\ub2e4. \uc774\uc5d0 \uadf8\uc758 \uce21\uadfc\ub4e4\uc740 SHEREG\uad6d\uacfc\uc758 \uc804\uc7c1\uc73c\ub85c \uad50\ud669\uccad\uacfc \uc655\uad6d\uc740 \uc815\uc2e0\uc774 \uc5c6\uc73c\ubbc0\ub85c \uc9c0\uae08\uc774 \uac00\uc7a5 \uc801\uc808\ud55c \ub54c\ub77c\uba70 \ub9ce\uc740 \uc0ac\ub78c\ub4e4\uc744 \uc704\ud574\uc11c\ub3c4 \ud589\uc0ac\ub97c \ud574\uc57c \ud55c\ub2e4\uace0 \uc8fc\uc7a5\ud55c\ub2e4. \uc0ac\ub78c\ub4e4\uc758 \ubc14\ub7a8\uc744 \uc678\uba74\ud558\uc9c0 \ubabb\ud55c \uc260\uc740 \uacb0\uad6d \ud589\uc0ac\ub97c \ud558\uae30\ub85c \ud558\uace0 \uc870\uc6a9\ud788 \uc544\ub3c8\uc744 \ubd88\ub7ec FETAE\ub85c \ub2e4\uc2dc \uac00\uc11c \uadf8 \uc720\uc9c0\uc5d0\uac8c\uc11c \uc5d8\ub85c\ud798\uc73c\ub85c\uc758 \uae38\uc744 \uc5ec\ub294 \ubc29\ubc95\uc758 \uadfc\uc6d0\uc5d0 \ub300\ud574 \uc870\uc0ac\ud574 \ub2ec\ub77c\ub294 \ubd80\ud0c1\uc744 \ud55c\ub2e4.": "In Fetae, Adon receives money and a letter for the resistance from a local patron. Meanwhile, Shereg\u2019s king opposes the pope\u2019s long war and calls for an end to the persecution of heretics. The papal court incites the other kingdoms to invade Shereg, plunging the continent into war. Rumours that the road to Elohim will soon open deepen the unrest. Back at the resistance headquarters in Teras, Adon overhears Shem arguing with his associates about a ceremony. The patron claims to know how to open the road to Elohim, but says a public gathering is needed. Shem fears a trap; his associates argue that the war makes this the right moment. Reluctantly, Shem agrees and asks Adon to investigate the source of the patron\u2019s claim.", "\ub2e4\uc2dc FETAE\ub85c \uac04 \uc544\ub3c8\uc740 \uadf8 \uc720\uc9c0\uc758 \uc9d1\uc5d0\uc11c \uc6b0\uc5f0\ud788 \uad50\ud669\uc758 \ud3b8\uc9c0\ub97c \ubc1c\uacac\ud558\uac8c \ub41c\ub2e4. \uadf8 \uc720\uc9c0\ub294 \uad50\ud669\uc774 \ud3c9\ubbfc \ub2e8\uccb4\uc758 \uc640\ud574\ub97c \ubaa9\uc801\uc73c\ub85c \ud3c9\ubbfc \ub2e8\uccb4\uc5d0 \uc811\uadfc\uc2dc\ud0a8 \uc0ac\ub78c\uc774\uc5c8\ub2e4. \uadf8\ub294 \ud3c9\ubbfc \ub2e8\uccb4\uc5d0 \uc790\uae08\uc744 \ub300\uc5b4 \uc8fc\uba74\uc11c \uadf8\ub4e4\uacfc\uc758 \uc758\uc2ec\uc744 \uc5c6\uc560\uace0 \uadf8\ub4e4\uc744 \uc5d8\ub85c\ud798 \uac15\ub9bc\uc81c\ub97c \ud1b5\ud574 \ubaa8\uc870\ub9ac \uc8fd\uc774\ub77c\ub294 \uba85\ub839\uc744 \ubc1b\uc544 \uc2e4\ud589\ud558\uace0 \uc788\uc5c8\ub2e4. \uc544\ub3c8\uc740 \uae09\ud788 TERAS\uc758 \ub808\uc9c0\uc2a4\ud0d5\uc2a4 \ubcf8\ubd80\ub85c \ub3cc\uc544\uc624\uc9c0\ub9cc \uc608\uc815\uc774 \uc55e\ub2f9\uaca8\uc9c4 \uac15\ub9bc\uc81c\ub97c \uc704\ud574 \ubaa8\ub450 JAKALE\ub85c \ub5a0\ub098 \ubc84\ub9b0 \ud6c4\uc600\uace0 \ub9c8\uc744 \ub178\uc778\uc73c\ub85c\ubd80\ud130 \uc260\uc774 \uc790\uc2e0\uc5d0\uac8c \uc4f4 \ud3b8\uc9c0\ub97c \uac74\ub124 \ubc1b\ub294\ub2e4. \uc260\uc740 \uc77c\uc774 \uc798\ubabb \ub418\uac8c \ub418\uba74 \uc21c\uc218 \uc885\uad50 \ub2e8\uccb4\uc758 \uc5ec\uc778\uc744 \ucc3e\uc544\uac00\ub77c\uace0 \ud55c\ub2e4.": "In Fetae, Adon finds a letter from the pope at the patron\u2019s house. The patron is a papal agent, ordered to gain the resistance\u2019s trust with money and then kill its members at the ceremony. Adon rushes back to Teras, but the ceremony has been brought forward and everyone has already left for Jakale. An elder gives Adon a letter from Shem, instructing him to seek the woman of the religious group if anything goes wrong.", "\ub4dc\ub514\uc5b4 \uac15\ub9bc\uc81c\uc758 \ub0a0\uc774 \uc624\uace0 \ub9ce\uc740 \uc0ac\ub78c\ub4e4\uc774 JAKALE \ub3d9\ucabd\uc758 \uc232\uc5d0 \ubaa8\uc600\ub2e4. \uc232\uc758 \uacf5\ud130\uc5d0\ub294 \uc81c\ub2e8\uc774 \ub9c8\ub828\ub418\uc5c8\uace0 \uc218\ub9ce\uc740 \uc0ac\ub78c\ub4e4\uc774 \uc81c\ub2e8\uc744 \ud5a5\ud574 \uc5c4\uc219\ud55c \ubd84\uc704\uae30\ub85c \uae30\ub3c4\ub97c \ub4dc\ub838\ub2e4. \uadf8\ub7ec\ub098 \uadf8\ub4e4 \uc55e\uc5d0 \ub098\ud0c0\ub09c \uac83\uc740 \uc5d8\ub85c\ud798\uc73c\ub85c\uc758 \uae38\uc774 \uc544\ub2cc \uad50\ud669\uc758 '\uac08\uac00\ub3cc' \ubd80\ub300\uc600\uace0 \uac15\ub9bc\uc81c\uc5d0 \ubaa8\uc778 \uc0ac\ub78c\ub4e4\uc740 '\uac08\uac00\ub3cc'\uc758 \ubd80\ub300\uc5d0 \ubb34\ucc38\ud788 \uc9d3\ubc1f\ud78c\ub2e4. \uc870\uae08 \ub2a6\uac8c \ub3c4\ucc29\ud55c \uc544\ub3c8\uc758 \ub208 \uc55e\uc5d0\uc11c \ub9ce\uc740 \uc0ac\ub78c\ub4e4\uc774 \uc0b4\uc721 \ub418\uc5c8\uace0 \ub808\uc9c0\uc2a4\ud0d5\uc2a4\uc758 \uc6b0\ub450\uba38\ub9ac \uc260\uc740 '\ub4dc\ub798\uace4'\ub4e4\uc758 \ud798\uc744 \ube4c\uc5b4 \ub300\ud56d\ud588\uc73c\ub098 \ub9ce\uc740 \uc218\uc758 '\uac08\uac00\ub3cc' \uc55e\uc5d0 \uaca9\uad6d \uc4f0\ub7ec\uc9c4\ub2e4. \uc260\uc740 \uc544\ub3c8\uc5d0\uac8c \uad50\ud669\uc744 \ucc98\ub2e8\ud574 \uc904 \uac83\uc744 \ubd80\ud0c1\ud558\uace0\ub294 \uc8fd\uc74c\uc744 \ub9de\uc774\ud55c\ub2e4. \uadf8\uc640 \ud568\uaed8 '\ub4dc\ub798\uace4'\ub4e4\ub3c4 \uc0ac\ub77c\uc9c4\ub2e4. \uc544\ub3c8\uc740 \ub0a8\uc740 \ub808\uc9c0\uc2a4\ud0d5\uc2a4 \uc77c\uc6d0\ub4e4\uc758 \ub3c4\uc6c0\uc73c\ub85c \uaca8\uc6b0 \ud0c8\ucd9c\ud558\uace0 YAEM\uc758 ANAN\uc73c\ub85c \uac04\ub2e4. ANAN\uc5d0\uc11c \uc544\ub3c8\uc740 \uadf8 \uc5ec\uc778\uc744 \ub9cc\ub098 \uc260\uc758 \uacfc\uac70\uc5d0 \ub300\ud574 \ub4e3\uac8c \ub41c\ub2e4. \uc260\uc740 \uc6d0\ub798 SHEREG\uad6d\uc758 \ub5a0\ub3cc\uc774\ub85c \uc6b0\uc5f0\ud788 \uc81c\uc0ac\uc7a5\uc758 \ub9c8\uc744\uc774 \uc788\uc5c8\ub358 \ud3d0\ud5c8\uc5d0 \uac00\uac8c \ub418\uace0 \uac70\uae30\uc11c \ud55c \ub178\uc778\uc744 \ub9cc\ub098 '\ub4dc\ub798\uace4' \uc18c\ud658\uc744 \ubc30\uc6b0\uac8c \ub41c\ub2e4. \uadf8 \ud6c4 \uadf8\ub294 \uadf8 \ud798\uc73c\ub85c \uad50\ud669\uc5d0 \ub300\uc801\ud558\uae30 \uc704\ud574 DEAMONLON\uc758 TERAS\uc5d0\uc11c \ub2e8\uccb4\ub97c \ud0a4\uc6cc\uc654\ub358 \uac83\uc774\ub2e4. \uc81c\uc0ac\uc7a5\uc758 \ub9c8\uc744\uc740 \uc77c\ubc18\uc778\uc5d0\uac8c\ub294 \uc54c\ub824\uc9c0\uc9c0 \uc54a\uc740 \ub9c8\uc744\uc774\uc5c8\ub2e4. \uc624\ub798 \uc804 \uc2e0\ub4e4\uc758 \uc804\uc7c1 \uc774\ud6c4, \ub300\ub300\ub85c \uc81c\uc0ac\uc7a5\uc758 \ub9c8\uc744\uc5d0\uc11c\ub294 \uc2e0\ub4e4\uc5d0 \ub300\ud55c \uacbd\ubc30\uac00 \uc774\ub8e8\uc5b4\uc838 \uc654\uc73c\uba70 \uadf8 \ub9c8\uc744\uc758 \uc81c\uc0ac\uc7a5\ub4e4\uc740 \uc218\ub9ce\uc740 \uac15\ub825\ud55c \ub9c8\ubc95\ub4e4\uc744 \uad6c\uc0ac\ud55c\ub2e4\ub294 \uc18c\ubb38\uc774\uc5c8\ub2e4. \uc774\uc5d0 \uc544\ub3c8\uc740 \uc5ec\uc778\uc774 \uc54c\ub824 \uc900 \uc81c\uc0ac\uc7a5\uc758 \ub9c8\uc744\uc744 \ucc3e\uc544 SHEREG\ub85c \ud5a5\ud55c\ub2e4.": "On the day of the ceremony, crowds gather at an altar in the woods east of Jakale. Instead of a road to Elohim, the pope\u2019s Gargadol appear and massacre them. Adon arrives too late. Shem and his dragons fight, but he is overwhelmed; dying, he asks Adon to defeat the pope. The dragons disappear. Survivors help Adon escape to Anan, where the woman tells him Shem learned to summon dragons from an old man in the ruins of a secret priests\u2019 village. Since the war of the gods, its priests have worshipped the gods and, it is said, wielded powerful magic. Adon sets out for Shereg to find it.", "\uc544\uc8fc \uc624\ub798 \uc804 \uc774\uc57c\uae30\ub780\ub2e4. \uc624\ub798 \uc804 \uc2e0\ub4e4\uc740 DMAN\uc744 \ub9cc\ub4e4\uace0 \uc0ac\ub78c\ub4e4\ub3c4 \ub9cc\ub4e4\uc5c8\uc9c0. \uc0ac\ub78c\ub4e4\uc740 DMAN\uc5d0\uc11c \ud3c9\ud654\ub86d\uac8c \uc9c0\ub0c8\uace0 \uc2e0\ub4e4\uc740 \uc0ac\ub78c\ub4e4\uc5d0\uac8c \ub9ce\uc740 \uac83\ub4e4\uc744 \uc8fc\uc5c8\uc5b4. \ud480\ub3c4 \ub098\ubb34\ub3c4... \ud558\ub298\uc744 \ub098\ub294 \uc0c8\ub3c4 \uc8fc\uc5c8\uc9c0. \uc2e0\ub4e4\uc740 \uc544\uc8fc \ud761\uc871\ud574 \ud588\ub2e8\ub2e4. \uadf8\ub7f0\ub370 \ub9d0\uc774\uc57c. \uc2dc\uac04\uc774 \uc9c0\ub098\uba74\uc11c \uc0ac\ub78c\ub4e4\uc740 \ud3c9\ud654\ub85c\uc6b4 \uc138\uc0c1\uc5d0 \uc2eb\uc99d\uc744 \ub290\ub080 \uac70\uc57c. \uc0ac\ub78c\ub4e4\uc740 \uc11c\ub85c\ub97c \uc2dc\uae30\ud558\uace0 \ubbf8\uc6cc\ud558\uba70 \uc11c\ub85c\ub97c \uc8fd\uc600\uc9c0. \uadf8\ub4e4\uc740 \uc804\uc7c1\uc744 \uc77c\uc0bc\uc73c\uba70 \uc2e0\ub4e4\uc774 \ub9cc\ub4e4\uc5b4 \uc900 \ub300\uc9c0\ub97c \ub354\ub7fd\ud614\uc9c0. \ud6c4... \ub108\ub3c4 \uc870\uae08\ub9cc \uc790\ub77c\uba74 \uc54c\uac8c \ub420 \uac70\ub2e4, \uc0ac\ub78c\ub4e4\uc774\ub780 \uc5bc\ub9c8\ub098 \uc5b4\ub9ac\uc11d\uc740 \uc874\uc7ac\ub4e4\uc778\uc9c0.\"": "\u201cThis happened long ago. The gods made DMAN and its people, who lived in peace. The gods gave them grass, trees and birds to fill the sky, and were pleased. But in time people grew tired of peace. They envied and hated one another, killed one another and scarred the land with war. When you are a little older, you will understand how foolish people can be.\u201d", "\uc774\ub7f0 \uc0ac\ub78c\ub4e4\uc744 \ub450\uace0 \uc2e0\ub4e4\uc740 \uace0\ubbfc\uc744 \ud588\ub2e8\ub2e4. \uc5b4\ub5a4 \uc2e0\ub4e4\uc740 \ubaa8\ub450 \uba78\ud574\ubc84\ub9ac\uc790\uace0 \ud588\uace0 \uc5b4\ub5a4 \uc2e0\ub4e4\uc740 \uadf8\ub4e4\uc774 \uc9c0\uce60 \ub54c\uae4c\uc9c0 \uae30\ub2e4\ub9ac\uc790\uace0 \ud588\ub2e8\ub2e4. \uc0ac\ub78c\ub4e4\uc5d0\uac8c \ud5c8\ub77d\ud55c \ub545\uc774\ub2c8 \uc0ac\ub78c\ub4e4\uc5d0\uac8c \ub9e1\uae30\uc790\uace0 \ud55c \uc2e0\ub4e4\ub3c4 \uc788\uc5c8\ub2e8\ub2e4. \uadf8\ub7ec\ub358 \uc911\uc5d0 \ud070 \uc0ac\uac74\uc774 \uc0dd\uae34 \uac70\uc57c. \uc0ac\ub78c\ub4e4\uc744 \ubbf8\uc6cc\ud558\ub358 \ud30c\uad34\uc758 \uc2e0 '\ud558\ub77c\uc2a4'\uac00 DMAN\uc5d0 \ub0b4\ub824\uc640 \uc0ac\ub78c\ub4e4\uc744 \ud559\uc0b4\ud558\uae30 \uc2dc\uc791\ud55c \uac70\uc57c. \uc774\uc5d0 \ucc3d\uc870\uc758 \uc2e0 '\ubc14\ub77c'\ub294 \ub9e4\uc6b0 \ud654\ub97c \ub0c8\uace0 \uace7 \uc2e0\ub4e4\uc740 \ub458\ub85c \uac08\ub77c\uc838 \uc2ec\ud558\uac8c \uc2f8\uc6e0\uc9c0. \uc778\uac04\ub4e4\uc758 \uc2f8\uc6c0\uc774 \uc2e0\ub4e4\uc758 \uc2f8\uc6c0\uc774 \ub418\uc5b4\ubc84\ub9b0 \uac70\uc57c. \ud558\ub298\uc740 \uc5b4\ub460\uc73c\ub85c \ub36e\uc774\uace0 \ubc14\ub2e4\ub294 \ud53c \ube5b\uc73c\ub85c \ubb3c\ub4e4\uc5c8\uc9c0. \ub545\uc5d0\ub294 \uc5b4\ub460\ub9cc \uac00\ub4dd \ucc28\uace0 \ub9ce\uc740 \uc0ac\ub78c\ub4e4\uc774 \uadf8 \uc804\uc7c1\uc73c\ub85c \uc8fd\uc5b4\uac14\uc9c0.\"": "\u201cThe gods debated what to do. Some wanted to destroy humanity; others wanted to wait until the fighting ended, or leave the land to the people to whom it had been given. Then Haras, the god of destruction, descended to DMAN and began slaughtering people. Bara, the god of creation, was furious, and the gods split into two warring sides. The sky darkened, the sea turned blood-red, and many people died.\u201d", "\ub05d\uc774 \uc5c6\uc5b4 \ubcf4\uc774\ub358 \uc804\uc7c1\uc740 \ud798\uc758 \uc2e0 '\uae30\ub4dc'\uac00 \ub3cc\ub85c \uac70\ub300\ud55c \uac70\uc778\ub4e4\uc744 \ub9cc\ub4e4\uba74\uc11c '\ud558\ub77c\uc2a4'\uc5d0\uac8c \uc720\ub9ac\ud558\uac8c \ub418\uc5c8\uc9c0. \uadf8\ub4e4\uc740 \uadf8 \uac70\uc778\ub4e4\uc744 '\uac08\uac00\ub3cc'\uc774\ub77c \ubd88\ub800\ub2e8\ub2e4. \uadf8\ub4e4\uc758 \ud798\uc740 \uc0c1\uc0c1\uc744 \ucd08\uc6d4\ud55c \uac83\uc774\uc5c8\ub2e8\ub2e4. \ub545\uc740 \ubb34\ucc38\ud788 \uc9d3\ubc1f\ud614\uace0 \ub9ce\uc740 \uc218\uc758 '\uac08\uac00\ub3cc'\ub4e4 \uc55e\uc5d0 '\ubc14\ub77c'\ub294 \ub2f9\ud669\ud588\ub2e8\ub2e4. \uc774\uc5d0 '\ubc14\ub77c'\uc758 \uc544\ub4e4\uc774\uc790 \uafc8\uc758 \uc2e0\uc778 '\ud560\ub86c'\uc740 '\uac08\uac00\ub3cc'\ub4e4\uc744 \ubb3c\ub9ac\uce58\uae30 \uc704\ud574 \ub4dc\ub798\uace4\ub4e4\uc744 \ub9cc\ub4e4\uc5b4 \ub0c8\ub2e8\ub2e4. \ub545\uc740 \uac70\ub300\ud55c '\uac08\uac00\ub3cc'\ub4e4\ub85c \uac00\ub4dd \ucc28\uace0 \ud558\ub298\uc740 \ub4dc\ub798\uace4\ub4e4\ub85c \ub4a4\ub36e\uc600\ub2e8\ub2e4. \uad49\uc7a5\ud588\uc744 \uac8c\uc57c. '\ud560\ub86c'\uc774 \ub9cc\ub4e0 \ub4dc\ub798\uace4\ub4e4\uc740 \uadf8 \uc544\ub984\ub2e4\uc6b4 \uc790\ud0dc\ub9cc\ud07c\uc774\ub098 \uc6a9\ub9f9\ud588\ub2e8\ub2e4. \uc601\uc6d0\ud560 \uac83 \uac19\uc558\ub358 \uc804\uc7c1\uc740 \ub9ce\uc740 \ub4dc\ub798\uace4\ub4e4\uc758 \uc8fd\uc744 \uc55e\uc5d0 \uc870\uae08\uc529 '\ubc14\ub77c'\uc5d0\uac8c \uc720\ub9ac\ud558\uac8c \ub418\uace0 \uacb0\uad6d '\ud558\ub77c\uc2a4'\ub294 \uc21c\ubc31\uc758 \ub4dc\ub798\uace4\uc744 \ud0c4 '\ud560\ub86c' \uc55e\uc5d0 \uc4f0\ub7ec\uc84c\ub2e8\ub2e4. '\ud558\ub77c\uc2a4'\ub294 DMAN \ub300\ub959 \uc5b4\ub518\uac00\uc5d0 \ubd09\uc778\ub418\uace0 \uadf8\ub97c \ub530\ub790\ub358 \ub9ce\uc740 \uc2e0\ub4e4\uc740 \uc720\ubc30\ub2f9\ud558\uac70\ub098 \uba40\ub9ac \ub5a0\ub098 \ubc84\ub838\ub2e8\ub2e4.\"": "\u201cThe seemingly endless war turned in Haras\u2019s favour when Gid, god of strength, made enormous stone giants called Gargadol. Their power was beyond imagining, and Bara was dismayed by their numbers. Bara\u2019s son Hallom, god of dreams, created dragons to fight them. The land filled with giants and the sky with dragons. Brave and beautiful, the dragons slowly turned the tide, though many died. At last Haras fell before Hallom, who rode a pure white dragon. Haras was sealed somewhere on DMAN, and the gods who followed him were exiled or departed.\u201d", "\uadf8\uc81c\uc11c\uc57c '\ubc14\ub77c'\ub294 \uc790\uc2e0\ub4e4\uc758 \uc804\uc7c1\uc73c\ub85c \uc8fd\uc5b4 \uac04 \ub9ce\uc740 \uc0ac\ub78c\ub4e4\uc744 \ub3cc\uc544\ubcf4\uac8c \ub418\uc5c8\uc5b4. \uadf8\ub4e4\uc744 \ubd88\uc30d\ud788 \uc5ec\uae34 '\ubc14\ub77c'\ub294 \uc601\uc6d0\uc758 \ub545 '\uc5d8\ub85c\ud798'\uc744 \ub9cc\ub4e4\uace0 \uc120\ud0dd\ubc1b\uc740 \uc790\ub4e4\uc744 \uadf8 \uacf3\uc73c\ub85c \ub370\ub824\uac14\ub2e8\ub2e4. '\ubc14\ub77c'\uc640 \ub9ce\uc740 \uc2e0\ub4e4\uc740 '\uc5d8\ub85c\ud798'\uc73c\ub85c \ub5a0\ub098\ubc84\ub9ac\uace0 DMAN\uc740 \ub0a8\uaca8\uc9c4 \uc0ac\ub78c\ub4e4\uc758 \uac83\uc774 \ub418\uc5c8\uc9c0. \uc601\uc6d0\uc744 \ud5c8\ub77d \ubc1b\uc9c0 \ubabb\ud55c \uc0ac\ub78c\ub4e4\uc758 \uac83 \ub9d0\uc774\ub2e4. \ub108\ub098 \ub098\ucc98\ub7fc. \"": "\u201cOnly then did Bara look upon the people who had died in the gods\u2019 war. Taking pity on them, Bara made Elohim, the land of eternity, and took the chosen there. Bara and many of the gods departed for Elohim, leaving DMAN to those who had not been granted eternity: people like you and me.\u201d", "\uadf8\ub7f0\ub370 '\ud558\ub77c\uc2a4'\uac00 \ubd09\uc778\ub420 \ub54c \ub0a8\uae34 \ub9d0\uc774 \uc788\ub2e4\ub294 \uad6c\ub098. \uc5b8\uc820\uac00 \uc0ac\ub78c\ub4e4\uc774 DMAN\uc744 \uac00\ub4dd \ucc44\uc6b8 \ub54c \uc790\uc2e0\uc774 \ub3cc\uc544 \uc62c \uac83\uc774\ub77c\uace0 \ub9d0\uc774\uc57c. \uc0ac\ub78c\ub4e4\uc740 \uadf8 \uc608\uc5b8\uc73c\ub85c \ub450\ub824\uc6cc\ud588\uace0 \uadf8\ub7f0 \uc0ac\ub78c\ub4e4 \uc55e\uc5d0 '\ubc14\ub77c'\ub294 \ud55c \uac00\uc9c0 \uc57d\uc18d\uc744 \ud588\uc5b4. '\ud558\ub77c\uc2a4'\uac00 \ub3cc\uc544 \uc62c \ub54c '\uc5d8\ub85c\ud798'\uc758 \uae38\uc774 \ub2e4\uc2dc \uc5f4\ub9b4 \uac83\uc774\ub77c\uace0. ... ... \uc598\uc57c. \ub09c \ub9d0\uc774\ub2e4 \ub9e4\uc77c \ubc24 '\uc5d8\ub85c\ud798'\uc744 \uafc8\uafbc\ub2e8\ub2e4. \ubbf8\uc6c0\uacfc \uace0\ud1b5\uc774 \uc5c6\ub294 \uadf8 \uacf3. \uc601\uc6d0\ud55c \uc0ac\ub791\ub9cc\uc774 \uc788\uc744 \uadf8\uacf3\uc744 \ub9d0\uc774\ub2e4.\" \ud560\uba38\ub2cc \uc5b8\uc81c\ub098 \uadf8\ub807\uac8c '\uc5d8\ub85c\ud798'\uc744 \ubc14\ub77c\ub2e4\uac00 \ub3cc\uc544\uac00\uc168\ub2e4.": "\u201cWhen Haras was sealed, he said he would return when people filled DMAN. The prophecy frightened them, so Bara promised that the road to Elohim would open again when Haras returned. Child, every night I dream of Elohim, a place without hatred or pain, where only eternal love remains.\u201d Grandmother longed for Elohim until the day she died.", "DMAN\uc5d0\ub294 \ub124 \uac1c\uc758 \ub098\ub77c( DEAMONLON, AESH, YAEM, SHEREG )\uac00 \uc788\uace0 \ub300\ub959\uc758 \ud55c \uac00\uc6b4\ub370\uc778 AESH\uc758 \uc911\uc2ec\uc5d0 \ubaa8\ub4e0 \ub300\ub959\uc758 \uc885\uad50\ub97c \uad00\uc7a5\ud558\ub294 \uad50\ud669\uccad\uc774 \uc788\uc5c8\ub2e4. \uad50\ud669\uccad\uc740 DMAN\uc758 \uc5ec\ub7ec \uc885\ud30c\ub4e4\uc744 \uc870\uc808\ud558\uba70 \uc885\uad50\uc801\uc778 \uc77c\ub4e4\uc744 \ub300\ud45c\ud558\uc600\uace0 \ub300\ub300\ub85c \uad50\ud669\uc740 \uc2e0\uad8c\uc73c\ub85c\uc368 DMAN \uac01 \ub098\ub77c\ub4e4\uc758 \uc655\uad8c\uc744 \uc870\uc815\ud558\ub294 \uc5ed\ud560\uc744 \ud574 \uc654\ub2e4. \uadf8\ub807\uac8c DMAN\uc758 \uc5ed\uc0ac\ub294 \uade0\ud615\uc744 \uc774\ub8e8\uc5b4\uac00\uba70 \ubc1c\uc804\ud574 \uc654\ub2e4. \uc0c8\ub85c\uc6b4 \uad50\ud669\uc774 \uad50\ud669\uccad\uc5d0 \uc758\ud574 \uc120\ubc1c\uc774 \ub418\uace0 DMAN\uc740 \uc0c8 \uad50\ud669\uc758 \ub178\ub825\uc73c\ub85c \ud3c9\ud654\ub85c\uc6b4 \uc2dc\ub300\ub97c \ub9de\uc774\ud55c \uac83\ucc98\ub7fc \ubcf4\uc600\ub2e4. \uba87 \ub144\uc774 \ud750\ub978 \ud6c4, \ud3c9\ud654\ub85c\uc640 \ubcf4\uc774\ub358 DMAN\uc740 \uad50\ud669\uc758 \uac11\uc791\uc2a4\ub7f0 \uc774\ub2e8 \uc120\ud3ec\uc5d0 \ud63c\ub780\uc5d0 \ube60\uc9c4\ub2e4. \uad50\ud669\uc740 \uc790\uc2e0\uc5d0\uac8c \ubc18\ub300\ud558\ub294 \ubaa8\ub4e0 \uc885\ud30c\ub4e4\uc5d0 \uc774\ub2e8 \uc120\uc5b8\uc744 \ud55c \uac83\uc774\ub2e4. \ub9ce\uc740 \uc885\ud30c\ub4e4\uc774 \uc774\ub2e8\uc73c\ub85c \uc120\uc5b8\ub418\uc5c8\uace0 \uadf8 \uc885\ud30c\ub4e4\uc758 \ub3c4\uc6c0\uc744 \ub9ce\uc774 \ubc1b\ub358 \uac01 \ub098\ub77c\ub4e4\uc740 \uad50\ud669\uc758 \uc2e0\uad8c \uc55e\uc5d0 \uc774\ub2e8\uc73c\ub85c \uc120\uc5b8\ub41c \uc885\ud30c\ub4e4\uc744 \uba40\ub9ac\ud560 \uc218\ubc16\uc5d0 \uc5c6\uc5c8\ub2e4. \uc0c1\ud669\uc740 \uc810\uc810 \ub098\ube60\uc838 \uad50\ud669\uc740 \ub9c8\uce68\ub0b4 \ubaa8\ub4e0 \uc774\ub2e8\ub4e4\uc744 \ucc99\uacb0\ud558\ub77c\ub294 \uc774\ub2e8 \ud0c4\uc555 \uc804\uc7c1\uc744 \uc120\uc5b8\ud558\uc600\ub2e4. \ub9ce\uc740 \uc9c0\uc5ed\uc5d0\uc11c \ub2e8\uc9c0 \uad50\ub9ac\uac00 \ub2e4\ub974\ub2e4\ub294 \uc774\uc720\ub85c \uc0ac\ub78c\ub4e4\uc774 \uc8fd\uc5b4\uac00\uace0 \uc774\ub2e8\uc73c\ub85c \uc120\uc5b8\ub41c \uc885\ud30c\ub4e4\uc740 \ud45c\uba74\uc801\uc778 \ubaa8\ub4e0 \ud65c\ub3d9\uc744 \uc911\uc9c0\ud55c \ucc44 \uc9c0\ud558\ub2e8\uccb4 \uac19\uc740 \ubaa8\uc784\uc73c\ub85c \uc804\ub77d\ud558\uace0 \ub9d0\uc558\ub2e4.": "DMAN has four kingdoms\u2014Deamonlon, Aesh, Yaem and Shereg. At the heart of Aesh, the papal court oversees the continent\u2019s religions. For generations its spiritual authority balanced the power of the kings. A new pope seemed to bring peace, but years later he declared every sect that opposed him heretical. Kingdoms distanced themselves from the condemned sects, and the pope declared a war to eradicate heresy. People died merely for holding different beliefs, and the sects went underground.", "'\uc544\ub3c8'\uc740 DAEMONLON\uad6d\uc758 \ud55c \uc2dc\uace8\uc5d0\uc11c \uc790\ub780 \uc80a\uc740\uc774\uc600\ub2e4. \uadf8\ub294 \ub530\ubd84\ud55c \uc2dc\uace8 \uc0dd\ud65c\uc5d0 \uc2eb\uc99d\uc744 \ub290\ub07c\uace0 \ubaa8\ud5d8\uc744 \ucc3e\uc544 \uc218\ub3c4\uc778 NAHASHI\ub85c\uc758 \uc5ec\ud589\uc744 \ub5a0\ub09c\ub2e4. \uc5ec\ud589\uc744 \ud1b5\ud574 \uadf8\ub294 \uc774\ub2e8 \ud0c4\uc555 \uc804\uc7c1\uacfc \uad50\ud669\uc758 \ud3ed\uc815\uc5d0 \ub300\ud574 \ucc28\uce30 \uc54c\uac8c \ub41c\ub2e4. \ud55c \ub2ec \uc5ec\uac04\uc758 \uc5ec\ud589\uc744 \ud1b5\ud574 \uc218\ub3c4\uc778 NAHASHI\uc5d0 \ub3c4\ucc29\ud55c \uadf8\ub294 \uc6b0\uc5f0\ud788 NAHASHI\uc758 \uc785\uad6c\uc5d0\uc11c \uacbd\ube44\ubcd1\uc5d0\uac8c \ucad3\uae30\uace0 \uc788\ub294 \ud55c \uc80a\uc740\uc774\ub97c \ub3c4\uc640\uc8fc\uac8c \ub418\uace0 \uadf8 \uc0ac\uac74\uc73c\ub85c \uacbd\ube44\ubcd1\uc5d0 \ucad3\uae30\ub294 \uc2e0\uc138\uac00 \ub41c\ub2e4. \uacbd\ube44\ubcd1\ub4e4\uc744 \ud53c\ud574 NAHASHI\ub97c \ubc97\uc5b4\ub098\uc790 \uadf8 \uc80a\uc740\uc774\ub294 \ub0a8\ucabd \ub9c8\uc744 TERAS\uc758 \uc8fc\uc810\uc5d0 \uc624\uba74 \ud6c4\uc0ac\ud558\uaca0\ub2e4\ub294 \ub9d0\ub9cc\uc744 \ub0a8\uae30\uace0 \ud669\uae09\ud788 \uc0ac\ub77c\uc9c4\ub2e4. NAHASHI\uc5d0 \ub4e4\uc5b4\uac08 \uc218 \uc5c6\uac8c \ub41c \uc544\ub3c8\uc740 \ud56d\uad6c\ub9c8\uc744 HARLOM\uc73c\ub85c \ud5a5\ud55c\ub2e4. HARLOM\uc5d0\uc11c \uc0ac\ub78c\ub4e4\uc758 \uc758\ub8b0\ub97c \ubc1b\uc544\uc11c \ubaa8\ud5d8\uac00\ub85c\uc368\uc758 \uba85\uc131\uc744 \uc313\uc544\uac00\ub358 \uc544\ub3c8\uc740 \uc5b4\ub290 \ub0a0 \ud55c \uc5ec\uc131\uc774 \ub9e1\uae34 \ud3b8\uc9c0\ub97c TERAS\uc758 \uc790\ud558 \uc870\uc9c1\uc758 \uc6b0\ub450\uba38\ub9ac\uc5d0\uac8c \uc804\ud574 \ub2ec\ub77c\ub294 \uc758\ub8b0\ub97c \ubc1b\ub294\ub2e4. TERAS\ub85c \uac04 \uc544\ub3c8\uc740 TERAS\uc758 \uc8fc\uc810\uc5d0\uc11c \uc790\uc2e0\uc774 \ub3c4\uc640\uc8fc\uc5c8\ub358 \uc80a\uc740\uc774\ub97c \ub9cc\ub09c\ub2e4. \uadf8 \uc80a\uc740\uc774\ub294 \uc790\uc2e0\uc744 \ud3c9\ubbfc \ub808\uc9c0\uc2a4\ud0d5\uc2a4\uc758 \uc77c\uc6d0\uc774\ub77c\uace0 \uc18c\uac1c\ud558\uace0 \uac19\uc774 \uad50\ud669\uacfc \uc774 \uacc4\uae09 \uc0ac\ud68c\ub97c \ud0c0\ud30c\ud558\uc790\ub294 \uc81c\uc758\ub97c \ubc1b\ub294\ub2e4. \uace0\ubbfc\ud558\ub358 \uc544\ub3c8\uc740 \uc77c\ub2e8 \ub9e1\uc740 \ud3b8\uc9c0\ub97c \uc804\ud574\uc8fc\uae30 \uc704\ud574 \uadf8 \uc80a\uc740\uc774\ub97c \ub530\ub77c \ub808\uc9c0\uc2a4\ud0d5\uc2a4\uc758 \ubcf8\ubd80\uac00 \uc788\ub294 \ub358\uc83c\uc73c\ub85c \ud5a5\ud55c\ub2e4.": "Adon, a young man from the countryside of Deamonlon, leaves his dull life to seek adventure in the capital, Nahashi. On the journey he learns of the war against heresy and the pope\u2019s tyranny. At the city gates he helps a young man fleeing guards and becomes a fugitive himself. The stranger promises a reward at a tavern in Teras, then disappears. Unable to enter Nahashi, Adon travels to the port of Harlom and makes a name as an adventurer. Later, a woman asks him to deliver a letter to the underground leader in Teras. There he meets the young man again, who reveals that he belongs to a commoners\u2019 resistance and asks Adon to help overthrow the pope and the class system. Adon follows him to the resistance headquarters to deliver the letter.", "\ub808\uc9c0\uc2a4\ud0d5\uc2a4\uc758 \uc6b0\ub450\uba38\ub9ac \uc260\uc740 \uc80a\uace0 \ub9e4\uc6b0 \uc5f4\uc815 \uc788\ub294 \uc0ac\ub78c\uc774\uc5c8\ub2e4. \uadf8\uc5d0\uac8c\uc11c\ub294 \uac15\ud55c \uce74\ub9ac\uc2a4\ub9c8\uc640 \uac70\uce60\uc9c0\ub9cc \uc21c\uc218\ud55c \uc815\uc2e0\uc744 \ub290\ub084 \uc218 \uc788\uc5c8\ub2e4. \uadf8\ub294 \ub4dc\ub798\uace4\uc744 \ub9c8\uc74c\ub300\ub85c \ubd80\ub838\uc73c\uba70 \uadf8 \ud798\uc73c\ub85c \uad50\ud669\uc758 \uad70\ub300\uc640 \ub300\uc801\ud558\ub294 \uc911\uc774\uc5c8\ub2e4. \uc260\uc740 \uc544\ub3c8\uc5d0\uac8c YAEM\uc758 ANAN\uc5d0 \uac00\uc11c \uadf8 \ud3b8\uc9c0\ub97c \uc900 \uc5ec\uc778\uc744 \ucc3e\uc544 \ub2f5\uc2e0\uc744 \uc804\ud574\uc904 \uac83\uc744 \uc544\ub3c8\uc5d0\uac8c \uc758\ub8b0\ud558\uace0 \uc544\ub3c8\uc740 \uadf8 \uae38\ub85c YAEM\uc73c\ub85c \ud5a5\ud55c\ub2e4. YAEM\uc758 ANAN\uc5d0\uc11c \uadf8 \uc5ec\uc778\uc744 \ucc3e\uae30\ub294 \uc5b4\ub835\uc9c0 \uc54a\uc558\ub2e4. \uadf8 \uc5ec\uc778\uc740 ANAN\uc758 \uc0ac\uc6d0\uc5d0\uc11c \uc27d\uac8c \ucc3e\uc744 \uc218 \uc788\uc5c8\uace0 \uadf8\ub140\uc5d0\uac8c \ud3b8\uc9c0\ub97c \uc804\ud574 \uc900 \uc544\ub3c8\uc740 \uadf8\ub140\uac00 \uad50\ud669\uc758 \ud3ed\uc815\uc5d0 \ud56d\uac70\ud558\uae30 \uc704\ud574 \uacb0\uc131\ub41c \uc9d1\ub2e8\uc758 \ub192\uc740 \uc704\uce58\uc5d0 \uc788\uc74c\uc744 \uc54c\uac8c \ub41c\ub2e4. \uad50\ud669\uc5d0\uac8c \uc774\ub2e8\uc73c\ub85c \uc120\uc5b8\uc744 \ubc1b\uc558\ub358 \ub9ce\uc740 \uc885\ud30c\ub4e4\uacfc \uad50\ud669\uccad\uc5d0\uc11c \uad50\ud669\uc758 \ud3ed\ub825\ud589\uc0ac\uc5d0 \ubc18\ub300\ud574\uc11c \uad50\ud669\uccad\uc744 \ube60\uc838 \ub098\uc628 \uc0ac\ub78c\ub4e4\uc740 \uc885\uad50\uc758 \uc6d0\ub798 \uc758\ubbf8\ub97c \ub418\ucc3e\uace0 \ud3c9\ud654\ub85c\uc6b4 \ub300\ub959\uc744 \ub9cc\ub4e4\uae30 \uc704\ud574 \uc21c\uc218 \uc885\uad50 \ub2e8\uccb4\ub97c \uacb0\uc131\ud558\uace0 \ub300\ud56d\ud558\ub294 \uc911\uc774\uc5c8\ub2e4. \uadf8 \ubb34\ub835, \ub300\ub959 \uc804\uccb4\ub294 \uc5d8\ub85c\ud798\uc774 \uace7 \uac15\ub9bc\ud560 \uac83\uc774\ub77c\ub294 \uc18c\ubb38\uc774 \ub3cc\uace0 \ub300\ub959 \uc804\uccb4\ub294 \uadf8 \uc18c\ubb38\uc5d0 \uc220\ub801\uac70\ub9b0\ub2e4. \ud55c \ud3b8 \uad50\ud669\uc774 \uc554\ud751\ub9c8\ubc95\uc73c\ub85c\uc368 \uc18c\ud658\ud55c '\uac08\uac00\ub3cc'\ub4e4\uc740 \ub300\ub959 \uc774\uacf3\uc800\uacf3\uc744 \ubb34\ucc38\ud788 \uc9d3\ubc1f\uace0 \ub2e4\ub154\ub2e4. \ub300\ub959 \uc774\uacf3 \uc800\uacf3\uc744 \ub5a0\ub3cc\uba70 \ubaa8\ud5d8\uac00\ub85c\uc368 \uc0b4\uc544\uac00\ub358 \uc544\ub3c8\uc740 \ub2e4\uc2dc TERAS\ub97c \ucc3e\uac8c \ub418\uace0 \ud3c9\ubbfc \ub808\uc9c0\uc2a4\ud0d5\uc2a4\uc758 \uc6b0\ub450\uba38\ub9ac\uc778 \uc260\uc5d0\uac8c\uc11c AESH\uc5d0 \uc788\ub294 FETAE\ub77c\ub294 \ub3c4\uc2dc\uc5d0\uc11c \ud55c \uc0ac\ub78c\uc744 \ub9cc\ub098 \uc870\uc9c1\uc5d0 \ud544\uc694\ud55c \uc790\uae08\uc744 \uc880 \ubc1b\uc544\uc640 \ub2ec\ub77c\ub294 \ubd80\ud0c1\uc744 \ubc1b\ub294\ub2e4. \uc260\uc740 \uadf8 \uc0ac\ub78c\uc758 \uc790\uae08 \uc870\ub2ec\ub85c \ub808\uc9c0\uc2a4\ud0d5\uc2a4\uc758 \uc0ac\ub78c\ub4e4\uc774 \uc0dd\uacc4\ub97c \uc720\uc9c0\ud558\uace0 \uc788\ub2e4\ub294 \ub9d0\uc744 \ud574\uc8fc\uace0\ub294 FETAE\ub85c\uc758 \uc5ec\ud589 \uc790\uae08\uc744 \uc900\ub2e4.": "Shem, the young, charismatic resistance leader, commands dragons against the pope\u2019s army. He asks Adon to deliver a reply to the woman in Anan, Yaem. Adon finds her at a temple and learns that she is a senior member of a religious group formed by condemned sects and former members of the papal court to restore peace and the true purpose of religion. Rumours spread that Elohim will soon descend, while Gargadol summoned by the pope\u2019s dark magic ravage the continent. Adon returns to Teras, where Shem asks him to collect funds from a supporter in Fetae, Aesh, whose contributions sustain the resistance.", "\ub4dc\ub85c\uc774\uc580 \ud648\ud398\uc774\uc9c0": "Droiyan website", "\uc0bc\uad6d\ud1b5\uc77c \ud648\ud398\uc774\uc9c0": "Samguk Tongil website", "E2SOFT \ud648\ud398\uc774\uc9c0": "E2SOFT website", "\uc6b4\uc601\uccb4\uc81c:Windows 95/98": "Operating system: Windows 95/98", "RAM:64MB\uc774\uc0c1": "RAM: 64 MB or more", "\ube44\ub514\uc624 \uce74\ub4dc:SVGA Video Card": "Video card: SVGA video card", "CD-ROM \uc18d\ub3c4:4X \uc774\uc0c1": "CD-ROM speed: 4x or faster", "\uacf5\uc9c0\uc0ac\ud56d": "Notices", "\ucd5c\uc2e0 \ud328\uce58\uce58(v1.40) \ud30c\uc77c\uc774 \uc644\uc131\ub418\uc5c8\uc2b5\ub2c8\ub2e4.": "The latest patch (v1.40) is now available.", "\ud328\uce58\ud30c\uc77c \ubc1b\uae30": "Download patch", "\uac8c\uc784 \uc815\ubcf4": "Game information", "\uac8c\uc784\ud2b9\uc9d5": "Features", "\uce90\ub9ad\ud130": "Characters", "\uc2a4\ud06c\ub9b0 \uc0f7": "Screenshots", "\uc2dc\uc2a4\ud15c \uc815\ubcf4": "System requirements", "\uac8c\uc2dc\ud310": "Board", "\uc815\ud1b5 RPG\uc640 \uc561\uc158 RPG\uc758 \uc0c8\ub85c\uc6b4 \ub9cc\ub0a8!": "A new meeting of classic RPG and action RPG!", "\ub514\uc2a4\ud3a0\uc740\u300c\ubb38\ud654\uad11\uad00\ubd80\u300d\uac00 \uc8fc\ucd5c\ud558\ub294 \uc6b0\uc218\uac8c\uc784 \uc0ac\uc804\uc81c\uc791\uc9c0\uc6d0\uc5d0 \ub2f9\uc120\ub418\uc5c8\uc73c\uba70 \ud0c4\ud0c4\ud55c \uc2dc\ub098\ub9ac\uc624\uc640 \ucc38\uc2e0\ud55c \uae30\ud68d\uc73c\ub85c \uc8fc\ubaa9\uc744 \ubc1b\uace0 \uc788\ub294 \uac8c\uc784\uc774\ub2e4. \ub514\uc2a4\ud3a0\uc5d0 \uad00\uc2ec\uc744 \uac00\uc9c0\uac8c \ud558\ub294 \uc694\uc18c\ub294 \uad6d\ub0b4 \uc778\uae30\ub97c \ub04c\uc5b4\ub358 \ub864\ud50c\ub808\uc789 \uac8c\uc784\ub4e4\uc758 \uc7a5\uc810\uc744 \ubaa8\ub450 \uac00\uc84c\uae30 \ub54c\ubb38\uc774\ub2e4. \uc2e4\uc2dc\uac04\uc73c\ub85c \uc9c0\uc18d\ub418\ub294 \uc804\ud22c, \ub192\uc740 \uc790\uc720\ub3c4, \uce90\ub9ad\ud130\uc758 \ub2e4\uc591\ud568\uc774 \uc7a5\uc810\uc774\uba70 \uc774\ub7ec\ud55c \uac83\ub4e4\uc740 \uc11c\uc591\uc758 \ub192\uc740 \uc790\uc720\ub3c4\uc640 \uc77c\ubcf8\uc2dd \uc2a4\ud1a0\ub9ac \uc804\uac1c\ubc29\uc2dd\uc758 \uc801\uc808\ud55c \uc870\ud654\uc5d0\uc11c \ub098\uc628\ub2e4. \uc9c0\uae08\uae4c\uc9c0 \ucd9c\uc2dc\ub41c \ub864\ud50c\ub808\uc789 \uac8c\uc784\ub4e4 \uc911\uc5d0\ub294 \uc9c0\ub098\uce58\uac8c \uc561\uc158\uc131\uc744 \ucd94\uad6c\ud558\uc5ec \uc131\uaca9\uc774 \ubcc0\uc9c8\ub418\uac70\ub098 \uc790\uc720\ub3c4\uc5d0 \uce58\uc911\ud55c \ub098\uba38\uc9c0 \uc9c0\ub8e8\ud55c \uac10\uc774 \ub098\ub294 \ubb38\uc81c\uc810\uc774 \uc788\uc5c8\ub294\ub370 \uc774 \ub450\uac00\uc9c0 \ud14c\ub9c8\ub97c \uc801\uc808\ud558\uac8c \uc870\ud654\uc2dc\ud0a8 \uac83\uc774 \uac00\uc7a5 \ud070 \ud2b9\uc0c9\uc774\ub77c\uace0 \ud560 \uc218 \uc788\ub2e4.": "Dispel was selected for a game pre-production award hosted by the Ministry of Culture and Tourism and has attracted attention for its strong story and fresh ideas. It combines the strengths of popular role-playing games: continuous real-time combat, extensive freedom and varied characters. Its distinctive feature is the balance between the freedom of Western RPGs and Japanese-style storytelling, avoiding both excessive action and the tedium that can come from freedom alone.", "120\uc5ec \uac00\uc9c0\uc758 \ube5b\uc758 \ub9c8\ubc95\uacfc \uc5b4\ub460\uc758 \ub9c8\ubc95": "About 120 light and dark spells", "\ub514\uc2a4\ud3a0\uc758 \uc138\uacc4\uad00\uc740 \uc120\uacfc \uc545\uc774 \uacf5\uc874\ud558\ub294 \uc120\uc545 \uacf5\uc874\uc124\uc5d0 \uae30\ubc18\uc744 \ub450\uace0 \uc788\ub2e4. \ub610\ud55c \uac8c\uc774\uba38\uc5d0\uac8c \ucd5c\ub300\ud55c\uc758 \uc790\uc720\ub3c4\uac00 \uc81c\uacf5\ub418\uae30 \ub54c\ubb38\uc5d0 \uc5b4\ub460\uc758 \uc804\uc0ac\ub3c4 \ub420 \uc218 \uc788\ub2e4. \ub9c8\ubc95\uc740 \ud06c\uac8c \uc120\uacfc \uc545\uc758 \ub9c8\ubc95\uc73c\ub85c \uad6c\ubd84\ub418\uc5b4 \uac01\uac01 \ube5b\uc758 \ub9c8\ubc95 80\uc5ec\uac00\uc9c0, \uc5b4\ub460\uc758 \ub9c8\ubc95 40\uc5ec \uac00\uc9c0\uac00 \uc874\uc7ac\ud55c\ub2e4.\u00b7\uc2a4\ud0ac(Skill)\uc2dc\uc2a4\ud15c\uc2a4\ud0ac \uc2dc\uc2a4\ud15c\uc774\ub780 \uc5b4\ub5a4 \ubb34\uae30\ub098 \ub9c8\ubc95\uc744 \uc790\uc8fc \uc0ac\uc6a9\ud558\ub294 \ub9cc\ud07c \uadf8 \uae30\uc220\uc774 \ub298\uc5b4\ub098\ub294 \uc2dc\uc2a4\ud15c\uc744 \ub9d0\ud55c\ub2e4. \uc774\ub7f0\ud55c \uae30\uc220\uc744 \uc0ac\uc6a9\ud568\uc73c\ub85c \uac8c\uc784\uc758 \ud765\ubbf8\uc694\uc18c\ub97c \ub192\uc774\uace0 \uc788\ub2e4.": "Dispel is based on a world in which good and evil coexist. The player has considerable freedom and can become a warrior of darkness. Magic is divided into good and evil, with around 80 light spells and 40 dark spells. The skill system improves weapons and magic as they are used, adding another dimension to play.", "\uce90\ub9ad\ud130 \ucc3d\uc870 \uc2dc\uc2a4\ud15c(\uc8fc\uc778\uacf5\uc744 \uc6d0\ud558\ub294\ub300\ub85c \ubc14\uafbc\ub2e4)": "Character creation: shape your own hero", "\ub514\uc2a4\ud3a0\uc740 \uac8c\uc774\uba38\uac00 \ucd5c\ucd08\ub85c \ubaa8\ud5d8\uc744 \uc2dc\uc791 \ud560 \ub54c \uc790\uc2e0\uc774 \uc6d0\ud558\ub294 \uce90\ub9ad\ud130\ub97c \ucc3d\uc870 \ud560 \uc218 \uc788\ub294 \uce90\ub9ad\ud130 \ucc3d\uc870 \uc2dc\uc2a4\ud15c\uc744 \ucc44\ud0dd\ud558\uace0 \uc788\uc5b4\uc11c \ub2e4\ub978 \uac8c\uc784\ub4e4\uacfc\ub294 \ub2ec\ub9ac \uadf8 \uce90\ub9ad\ud130\uc5d0 \ub300\ud55c \uc560\ucc29\uc744 \ub290\ub084 \uc218 \uc788\ub2e4.": "At the start of the adventure, players can create the character they want, making it easier to form a personal connection with their hero.", "\uc2e4\uc0ac\uc640 \uac19\uc740 \uadf8\ub798\ud53d": "Lifelike graphics", "\ub514\uc2a4\ud3a0\uc5d0 \ub4f1\uc7a5\ud558\ub294 \ubaa8\ub4e0 \uce90\ub9ad\ud130\uc640 \ubc30\uacbd \ub4f1\uc740 \ubaa8\ub450 3D\ub79c\ub354\ub9c1\uc73c\ub85c \ucc98\ub9ac\ud588\uace0 \uc5ec\uae30\uc5d0 \uc54c\ud30c\ube14\ub80c\ub529, \uae00\ub77c\uc2a4 \ud6a8\uacfc, \ub808\uc774\ud2b8\ub808\uc774\uc2f1 \ud6a8\uacfc\ub4f1 \ub2e4\uc591\ud55c 3D \uae30\ubc95\uc744 \ub3c4\uc785\ud588\ub2e4.": "Characters and backgrounds are rendered in 3D using techniques including alpha blending, glass effects and ray tracing.", "\uac15\ub825\ud55c 3D \ud6a8\uacfc": "Powerful 3D effects", "\uad11\uc6d0 \ud6a8\uacfc, \uae00\ub77c\uc2a4 \ud6a8\uacfc, \ub808\uc774\ud2b8 \ub808\uc774\uc2f1 \ud6a8\uacfc (\ubc18\uc0ac \ud6a8\uacfc) \ub4f1\uc744 \uc0ac\uc6a9\ud558\uc5ec 3D \uac8c\uc784\uc5d0\uc11c\ub098 \uac00\ub2a5\ud588\ub358 \ud6a8\uacfc\ub4e4\uc744 \ub514\uc2a4\ud3a0\uc5d0\uc11c \uacbd\ud5d8\ud560 \uc218 \uc788\ub2e4.": "Lighting, glass and ray-traced reflections bring effects associated with 3D games to Dispel.", "\ubca0\ud2c0 \uc11c\ubc84 \uc9c0\uc6d0\uc758 \ub124\ud2b8\uc6cd \uc2dc\uc2a4\ud15c": "Network play with battle server support", "\ub514\uc544\ube14\ub85c \ubca0\ud2c0\ub137\uacfc \uac19\uc774 \ub611\uac19\uc740 \ubaa8\uc2b5\uc758 \uc804\uc0ac \ub9c8\ubc95\uc0ac\ub294 \ub514\uc2a4\ud3a0\uc5d0 \uc5c6\ub2e4. \uadf8 \uc774\uc720\uc778 \uc989 Dispel\uc5d0\uc11c\ub294 \uc804\ud600 \ub2e4\ub978 \ubaa8\uc2b5\uc758 \uce90\ub9ad\ud130\ub97c \uc218\ub3c4 \uc5c6\uc774 \ub9cc\ub4e4 \uc218 \uc788\uae30 \ub54c\ubb38. \ud655\uc2e4\ud788 \uad6c\ubd84\uc774 \uac00\ub294 \uc778\ubb3c\ub4e4\ub85c \ub124\ud2b8\uc6cd\uc744 \ud1b5\ud574 \uce5c\uad6c\ub97c \ub9cc\ub4e4\uace0 \ub514\uc2a4\ud3a0\ub9cc\uc758 \uc138\uacc4\ub97c \ucc3d\uc870\ud574 \ub098\uac08 \uc218 \uc788\ub2e4. \uc774\uac83\uc740 \uace7 \ud328\uce58 \ud30c\uc77c\ub85c \uc9c0\uc6d0 \uc608\uc815\uc774\ub2e4.": "Unlike the identical-looking warriors and mages of Diablo\u2019s Battle.net, Dispel lets players create countless distinct characters, make friends over a network and build their own world. Support was planned in a future patch."};
  const storageKey = 'dispel-language';
  const nodes = [];
  const normalise = text => text.replace(/\s+/g, ' ').trim();
  let english = false;
  try { english = localStorage.getItem(storageKey) === 'en'; } catch (_) {}

  function init() {
    const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT, {
      acceptNode(node) {
        return /^(SCRIPT|STYLE|NOSCRIPT)$/.test(node.parentElement?.tagName || '')
          ? NodeFilter.FILTER_REJECT : NodeFilter.FILTER_ACCEPT;
      }
    });
    while (walker.nextNode()) {
      const node = walker.currentNode;
      const translated = translations[normalise(node.nodeValue)];
      if (translated) nodes.push({node, original: node.nodeValue, translated});
    }

    const style = document.createElement('style');
    style.textContent = `
      .language-control { text-align:center; margin: 7px 0 0; }
      .language-control button { color:#ddd; background:#282828; border:1px solid #888; border-radius:2px; padding:3px 10px; font:12px Arial,sans-serif; cursor:pointer; }
      .language-control button:hover, .language-control button:focus-visible { color:#fff; border-color:#ffa029; }
      .language-control.floating { position:fixed; bottom:12px; right:12px; z-index:1000; }
      .translated-menu-wrap { display:inline-block; position:relative; line-height:0; }
      .translated-menu { position:absolute; left:127px; top:70px; width:424px; height:19px; display:flex; align-items:center; background:#000; line-height:normal; }
      .translated-menu a { box-sizing:border-box; color:silver; text-decoration:none; text-align:center; font:9px Arial,sans-serif; text-transform:uppercase; white-space:nowrap; }
      .translated-menu a:nth-child(4) { font-size:8.5px; }
      .translated-menu a:hover, .translated-menu a:focus-visible { color:#fff; text-decoration:underline; }
      .translated-menu[hidden] { display:none; }
    `;
    document.head.appendChild(style);

    let control = document.getElementById('language-switch');
    if (!control) {
      control = document.createElement('div');
      control.className = 'language-control floating';
      document.body.appendChild(control);
    } else control.className = 'language-control';
    const button = document.createElement('button');
    button.type = 'button';
    control.appendChild(button);

    // The original navigation is an image map. Cover only its Korean labels
    // in English mode, leaving the original image and artwork in place.
    const menu = document.querySelector('img[usemap="#ImageMap1"]');
    let overlay;
    if (menu) {
      const wrapper = document.createElement('span');
      wrapper.className = 'translated-menu-wrap';
      menu.parentNode.insertBefore(wrapper, menu);
      wrapper.appendChild(menu);
      overlay = document.createElement('span');
      overlay.className = 'translated-menu';
      overlay.hidden = true;
      const paths = ['../story%20of%20dispel%200/story%20of%20dispel.htm?langsite=8', '../feature/feature%20of%20dispel.htm?langsite=8', '../screenshot/screen%20shot%20of%20dispel.htm?langsite=8', '../char/dispel%20characters.htm?langsite=8', '../system/system.htm?langsite=8', 'https://web.archive.org/web/20010417052826/http://www.e2soft.com/dispel/html/board.htm'];
      const labels = ['Story', 'Features', 'Screens', 'Characters', 'System', 'Board'];
      const widths = [75, 82, 76, 65, 80, 46];
      const areas = [...document.querySelectorAll('map[name="ImageMap1"] area')];
      labels.forEach((label, index) => {
        const a = document.createElement('a');
        a.textContent = label;
        a.style.width = widths[index] + 'px';
        a.href = areas[index]?.getAttribute('href') || paths[index];
        overlay.appendChild(a);
      });
      wrapper.appendChild(overlay);
    }
    function render() {
      nodes.forEach(({node, original, translated}) => {
        if (!english) { node.nodeValue = original; return; }
        const leading = original.match(/^\s*/)[0];
        const trailing = original.match(/\s*$/)[0];
        node.nodeValue = leading + translated + trailing;
      });
      document.documentElement.lang = english ? 'en' : 'ko';
      button.textContent = english ? '한국어' : 'English';
      button.setAttribute('aria-label', english ? 'Switch to Korean' : 'Switch to English');
      if (overlay) overlay.hidden = !english;
    }
    button.addEventListener('click', () => {
      english = !english;
      try { localStorage.setItem(storageKey, english ? 'en' : 'ko'); } catch (_) {}
      render();
    });
    render();
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init);
  else init();
})();
